.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 2rem;
  background: radial-gradient(circle at top left, #dbeafe, transparent 48%), #f8fafc;
  color: #0f172a;
  font-family: Arial, Helvetica, sans-serif;
}

.card {
  width: min(100%, 34rem);
  padding: clamp(2rem, 6vw, 3.5rem);
  border: 1px solid #e2e8f0;
  border-radius: 1.5rem;
  background: #fff;
  box-shadow: 0 24px 64px rgba(15, 23, 42, 0.09);
}

.badge {
  display: inline-block;
  padding: 0.5rem 0.75rem;
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  font-size: 0.875rem;
  font-weight: 700;
}

.card h1 {
  margin: 1.5rem 0 0.75rem;
  font-size: clamp(2rem, 5vw, 2.75rem);
  line-height: 1.15;
  letter-spacing: -0.04em;
}

.card p {
  margin: 0 0 2rem;
  color: #475569;
  line-height: 1.65;
}

.link {
  display: inline-flex;
  gap: 0.5rem;
  align-items: center;
  padding: 0.8rem 1.1rem;
  border-radius: 0.75rem;
  background: #1d4ed8;
  color: #fff;
  font-weight: 600;
  text-decoration: none;
}

.link:hover,
.link:focus-visible {
  background: #1e40af;
}

.link:focus-visible {
  outline: 3px solid #93c5fd;
  outline-offset: 3px;
}

